import {chromium,expect} from '@playwright/test';
import {readFile,writeFile,mkdir} from 'node:fs/promises';
const rec=JSON.parse(await readFile('.local/step07-review/evidence/integrated-recovery.json','utf8')),base='http://127.0.0.1:4377',out='.local/step07-review/evidence/browser-followup';await mkdir(out,{recursive:true});const browser=await chromium.launch({headless:true}),context=await browser.newContext({viewport:{width:1280,height:960}});await context.addInitScript(()=>{let id=1,q=new Map();window.requestAnimationFrame=f=>{const n=id++;q.set(n,f);return n};window.cancelAnimationFrame=n=>q.delete(n);window.__reviewTick=t=>{const old=[...q];q.clear();for(const[,f]of old)f(t)}});
const page=await context.newPage(),log={network:[],pageErrors:[],clock:[]},pending=[];page.on('response',r=>{if(r.url().includes('/api/')){const n={url:r.url(),method:r.request().method(),status:r.status()};log.network.push(n);if(r.status()>=400)pending.push((async()=>{try{n.body=await r.json()}catch{}})())}});page.on('pageerror',e=>log.pageErrors.push(e.message));const projects=(await(await fetch(base+'/api/projects')).json()).projects;
const select=async id=>{await page.getByRole('button',{name:projects.find(p=>p.id===id).name,exact:true}).click();await expect.poll(async()=>page.getByAltText('当前配方处理水面').evaluate(i=>i.complete&&i.naturalWidth===96)).toBe(true);await expect(page.locator('canvas[aria-label="交付拼接预览"]')).toBeVisible({timeout:45000})};const c=()=>page.locator('canvas[aria-label="交付拼接预览"]');const pixels=async(selector,name)=>{const data=await page.locator(selector).evaluate(c=>c.toDataURL().split(',')[1]);await writeFile(out+'/'+name+'.png',Buffer.from(data,'base64'))};
try{await page.goto(base);await select(rec.legacy.project);await select(rec.browserProject);await select(rec.legacy.project);await select(rec.browserProject);await page.screenshot({path:out+'/project-switch-stable.png',fullPage:true});log.stableProcessedNaturalWidth=await page.getByAltText('当前配方处理水面').evaluate(i=>i.naturalWidth);
const sources=await page.evaluate(async()=>{const id=localStorage.getItem('studio-project'),s=await(await fetch(`/api/projects/${id}/studio`)).json();return[0,1,2].map(n=>s.sources.find(r=>r.id===document.querySelectorAll('.components select')[n+1].value))});log.sources=sources;for(let n=0;n<3;n++)await writeFile(out+'/source-'+n+'.png',Buffer.from(await(await fetch(base+sources[n].url)).arrayBuffer()));
await page.getByLabel('实际构建').selectOption(rec.first);await page.getByLabel('检查场景').selectOption('isolated');await expect(c()).toHaveAttribute('data-build-id',rec.first,{timeout:45000});await expect(c()).toHaveAttribute('data-scene','isolated');await page.getByRole('button',{name:'状态 0 · 源帧 0',exact:true}).click();await page.getByRole('button',{name:'播放',exact:true}).click();await page.getByRole('button',{name:'播放源水面',exact:true}).click();await page.evaluate(()=>window.__reviewTick(0));
for(let u=1;u<=360;u++){await page.evaluate(t=>window.__reviewTick(t),u*1000/60);if([29,30,59,60,89,90,119,120,239,240,359,360].includes(u)){await page.waitForTimeout(3);expect(Number(await c().getAttribute('data-updates'))).toBe(u);const s=Number(await c().getAttribute('data-state'));expect(s).toBe(Math.floor(u/30)%4);await pixels('canvas[aria-label="交付拼接预览"]','delivery-update-'+u);await pixels('canvas[aria-label="创作源水面动画"]','source-update-'+u);log.clock.push({update:u,state:s,sourceFrame:[0,1,2,1][s]})}}expect(log.pageErrors).toEqual([]);log.result='PASS_RENDERING_AND_STABLE_CONTROLS';}catch(e){log.result='FAIL';log.failure=String(e);await page.screenshot({path:out+'/failure.png',fullPage:true}).catch(()=>{});throw e}finally{await Promise.allSettled(pending);await writeFile(out+'/evidence.json',JSON.stringify(log,null,2)+'\n');await browser.close()}

