import {chromium,expect} from '@playwright/test';
import {readFile,writeFile,mkdir} from 'node:fs/promises';
import {createHash} from 'node:crypto';
const {PrismaClient}=await import('../../../apps/api/node_modules/@prisma/client/default.js');
const e=JSON.parse(await readFile('.local/step07-review/restored-env.json','utf8')),record=JSON.parse(await readFile('.local/step07-review/evidence/integrated-recovery.json','utf8')),oldBrowser=JSON.parse(await readFile('.local/step07-review/evidence/browser/evidence.json','utf8'));
const db=new PrismaClient({datasources:{db:{url:e.url}}}),base='http://127.0.0.1:4377',out='.local/step07-review/evidence/restored-browser';await mkdir(out,{recursive:true});const sha=b=>createHash('sha256').update(b).digest('hex'),log={network:[],pageErrors:[],console:[],downloads:[]};
const count=async()=>({exportCount:await db.finalExport.count({where:{buildId:record.legacy.build}}),build:await db.build.findUnique({where:{id:record.legacy.build}}),packVersions:await db.packVersion.count(),slotVersions:await db.slotVersion.count(),project:await db.project.findUnique({where:{id:record.legacy.project}})});
const before=await count();assert(before.exportCount===0);function assert(v){if(!v)throw Error('independent restored assertion')};
for(const endpoint of ['preview?scene=pond','download']){const r=await fetch(`${base}/api/projects/${record.legacy.project}/builds/${record.legacy.build}/${endpoint}`);assert(r.status===409);await r.arrayBuffer()};const endpoint=`${base}/api/projects/${record.legacy.project}/builds/${record.legacy.build}/export`;for(const headers of [{'Content-Type':'application/json',Origin:'https://bad.invalid','X-Tileset-Client':'local-v1'},{'Content-Type':'application/json',Origin:base}]){const r=await fetch(endpoint,{method:'POST',headers,body:'{}'});assert(r.status===403);await r.arrayBuffer()};expect(await count()).toEqual(before);log.oldReadsBeforeExport='409; no write';log.badPostOriginClient=[403,403];
const browser=await chromium.launch({headless:true});const page=await browser.newPage({viewport:{width:1280,height:960},acceptDownloads:true});page.on('response',r=>{if(r.url().includes('/api/'))log.network.push({url:r.url(),status:r.status(),method:r.request().method()})});page.on('pageerror',e=>log.pageErrors.push(e.message));page.on('console',m=>log.console.push({type:m.type(),text:m.text()}));
const select=async id=>{const projects=(await(await fetch(base+'/api/projects')).json()).projects;await page.getByRole('button',{name:projects.find(p=>p.id===id).name,exact:true}).click()};const ready=async b=>{await expect(page.locator('canvas[aria-label="交付拼接预览"]')).toHaveAttribute('data-build-id',b,{timeout:45000});await expect(page.getByText('画布已就绪 · 实际导出图集',{exact:false})).toBeVisible({timeout:30000})};const download=async name=>{const wait=page.waitForEvent('download');await page.getByRole('link',{name:'下载此构建的标准 MZ 素材包 ZIP'}).click();const dl=await wait;await dl.saveAs(out+'/'+name+'.zip');const b=await readFile(out+'/'+name+'.zip');log.downloads.push({name,sha256:sha(b),filename:dl.suggestedFilename()});return sha(b)};
try{await page.goto(base);await select(record.legacy.project);await ready(record.legacy.build);await page.getByLabel('检查场景').selectOption('holes');await ready(record.legacy.build);await page.screenshot({path:out+'/01-legacy-converted.png',fullPage:true});await download('legacy');const after=await count();expect(after.exportCount).toBe(1);expect({...after,exportCount:0}).toEqual(before);expect(after.build.manifestSha).toBe(record.legacy.internalManifestSha);assert(log.network.some(x=>x.method==='POST'&&x.url===endpoint&&x.status===200));log.legacyBefore=before;log.legacyAfter=after;
await select(record.browserProject);await ready(record.oldSuccessful);await page.screenshot({path:out+'/02-current-restored.png',fullPage:true});await page.getByLabel('实际构建').selectOption(record.first);await ready(record.first);assert(await download('history')===oldBrowser.downloads.find(x=>x.name==='first').sha256);await page.screenshot({path:out+'/03-history-restored.png',fullPage:true});
await page.getByLabel('实际构建').selectOption(record.oldSuccessful);await ready(record.oldSuccessful);const wait=page.waitForResponse(r=>r.url().endsWith('/builds')&&r.request().method()==='POST');await page.getByRole('button',{name:'构建当前配套',exact:true}).click();const j=await(await wait).json();const item=page.getByRole('list',{name:'构建任务'}).getByRole('listitem').filter({hasText:j.id.slice(0,8)});await expect(item).toContainText('完成',{timeout:90000});await item.getByRole('button',{name:'查看这次实际构建'}).click();const built=await page.getByLabel('实际构建').inputValue();await ready(built);assert(built!==record.oldSuccessful);log.rebuilt=built;await download('rebuilt');await page.screenshot({path:out+'/04-rebuilt.png',fullPage:true});await page.reload();await ready(built);assert((await db.project.findUnique({where:{id:record.browserProject}})).successfulBuildId===built);log.result='PASS';expect(log.pageErrors).toEqual([])}catch(e){log.result='FAIL';log.failure=String(e);await page.screenshot({path:out+'/failure.png',fullPage:true}).catch(()=>{});throw e}finally{await writeFile(out+'/evidence.json',JSON.stringify(log,null,2)+'\n');await browser.close();await db.$disconnect()}
